  id, kind, title, exam, subject, topic, difficulty, statement, choices, correct_key, explanation, source_url, source_year, origin, published, metadata, created_at, updated_at
) VALUES (
  '60fe7300-c704-4ce5-aa84-331cf9a9cfa4', 'question', 'FUVEST 2018 — Questão 35', 'FUVEST', 'Natureza', 'Biologia', 3, 'Borboleta, lula e avestruz têm como principal excreta
nitrogenado, respectivamente,', '[{"key": "A", "text": "ácido úrico, amônia e ácido úrico."}, {"key": "B", "text": "ácido úrico, ureia e amônia."}, {"key": "C", "text": "amônia, ácido úrico e amônia."}, {"key": "D", "text": "amônia, ureia e ácido úrico."}, {"key": "E", "text": "ureia, amônia e ácido úrico."}]'::jsonb, 'A', '', 'https://www.fuvest.br/vestibular-da-usp/provas-e-gabaritos/', 2018, 'official', true, '{"bluex_id": "USP_2018_35", "assuntos_originais": ["biology"]}'::jsonb, '2026-10-16 19:55:42.062094+00', '2026-10-16 19:55:41.726+00'
