  id, kind, title, exam, subject, topic, difficulty, statement, choices, correct_key, explanation, source_url, source_year, origin, published, metadata, created_at, updated_at
) VALUES (
  '03644641-3ce5-4454-aabf-a10eeb56c5a5', 'question', 'FUVEST 2019 — Questão 28', 'FUVEST', 'Natureza', 'Biologia', 3, 'Um organismo multicelular, fotossintetizante, que possui
sistema vascular e não possui frutos ou sementes é uma', '[{"key": "A", "text": "alga."}, {"key": "B", "text": "briófita."}, {"key": "C", "text": "pteridófita."}, {"key": "D", "text": "gimnosperma."}, {"key": "E", "text": "angiosperma."}]'::jsonb, 'C', '', 'https://www.fuvest.br/vestibular-da-usp/provas-e-gabaritos/', 2019, 'official', true, '{"bluex_id": "USP_2019_28", "assuntos_originais": ["biology"]}'::jsonb, '2026-10-16 19:55:46.046449+00', '2026-10-16 19:55:45.95+00'
