INSERT INTO public.academic_items (
  id, kind, title, exam, subject, topic, difficulty, statement, choices, correct_key, explanation, source_url, source_year, origin, published, metadata, created_at, updated_at
) VALUES (
  'f8c56832-f266-47c3-bced-6de3a49bf597', 'question', 'FUVEST 2020 — Questão 14', 'FUVEST', 'Matematica', 'Matemática', 3, 'Se, em 15 anos, o salário mínimo teve um aumento nominal 
de 300% e a inflação foi de 100%, é correto afirmar que o 
aumento real do salário mínimo, nesse período, foi de', '[{"key": "A", "text": "50%."}, {"key": "B", "text": "100%."}, {"key": "C", "text": "150%."}, {"key": "D", "text": "200%."}, {"key": "E", "text": "250%."}]'::jsonb, 'B', '', 'https://www.fuvest.br/vestibular-da-usp/provas-e-gabaritos/', 2020, 'official', true, '{"bluex_id": "USP_2020_14", "assuntos_originais": ["mathematics"]}'::jsonb, '2026-10-16 19:55:48.047186+00', '2026-10-16 19:55:47.958+00'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.academic_items (
  id, kind, title, exam, subject, topic, difficulty, statement, choices, correct_key, explanation, source_url, source_year, origin, published, metadata, created_at, updated_at
) VALUES (
  'ff0216f8-4929-4f00-b801-e31a84d1d285', 'question', 'FUVEST 2020 — Questão 17', 'FUVEST', 'Matematica', 'Matemática', 3, 'A menor esfera na qual um paralelepípedo reto‐retângulo de 
medidas 7 cm × 4 cm × 4 cm está inscrito tem diâmetro de', '[{"key": "A", "text": "9 cm."}, {"key": "B", "text": "10 cm."}, {"key": "C", "text": "11 cm."}, {"key": "D", "text": "12 cm."}, {"key": "E", "text": "15 cm."}]'::jsonb, 'A', '', 'https://www.fuvest.br/vestibular-da-usp/provas-e-gabaritos/', 2020, 'official', true, '{"bluex_id": "USP_2020_17", "assuntos_originais": ["mathematics"]}'::jsonb, '2026-10-16 19:55:48.047186+00', '2026-10-16 19:55:47.958+00'
