INSERT INTO public.academic_items (
  id, kind, title, exam, subject, topic, difficulty, statement, choices, correct_key, explanation, source_url, source_year, origin, published, metadata, created_at, updated_at
) VALUES (
  'a8110535-6407-457e-9430-443f9537c566', 'question', 'FUVEST 2021 — Questão 12', 'FUVEST', 'Matematica', 'Matemática', 3, 'Um marceneiro possui um pedaço de madeira no formato de um triângulo retângulo, cujos catetos medem 12 cm e 35 cm.
 A partir desta peça, ele precisa extrair o maior quadrado possível, de tal forma que um dos ângulos retos do quadrado coincida 
 com o ângulo reto do triângulo. A medida do lado do quadrado desejado pelo marceneiro está mais próxima de', '[{"key": "A", "text": "8,0 cm"}, {"key": "B", "text": "8,5 cm"}, {"key": "C", "text": "9,0 cm"}, {"key": "D", "text": "9,5 cm"}, {"key": "E", "text": "10,0 cm"}]'::jsonb, 'C', '', 'https://www.fuvest.br/vestibular-da-usp/provas-e-gabaritos/', 2021, 'official', true, '{"bluex_id": "USP_2021_12", "assuntos_originais": ["mathematics"]}'::jsonb, '2026-10-16 19:55:52.109277+00', '2026-10-16 19:55:52.012+00'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.academic_items (
