) VALUES (
  '6a10a5b8-df4f-49b4-82cc-7444acdd1f5a', 'question', 'Unicamp 2020 — Questão 39', 'Unicamp', 'Matematica', 'Matemática', 3, 'Sabendo que 𝑝 é um número real, considere a matriz
A = [[𝑝, 2], [0, 𝑝]] e sua transposta 𝐴^T. Se 𝐴+𝐴^T é singular (não
invertível), então', '[{"key": "A", "text": "𝑝 = 0."}, {"key": "B", "text": "|𝑝| = 1."}, {"key": "C", "text": "|𝑝| = 2."}, {"key": "D", "text": "𝑝 = 3."}]'::jsonb, 'B', '', 'https://www.comvest.unicamp.br/vestibulares-anteriores/provas-e-gabaritos/', 2020, 'official', true, '{"bluex_id": "UNICAMP_2020_39", "assuntos_originais": ["mathematics"]}'::jsonb, '2026-10-16 19:55:30.178949+00', '2026-10-16 19:55:30.089+00'
