INSERT INTO public.academic_items (
  id, kind, title, exam, subject, topic, difficulty, statement, choices, correct_key, explanation, source_url, source_year, origin, published, metadata, created_at, updated_at
) VALUES (
  '6fc1a4c5-a964-4a9f-a575-3c7cddc43d06', 'question', 'Unicamp 2020 — Questão 35', 'Unicamp', 'Matematica', 'Matemática', 3, 'Sabendo que 𝑎 é um número real, considere a função
𝑓(𝑥)=𝑎𝑥+2, definida para todo número real 𝑥. Se
𝑓(𝑓(1))=1, então', '[{"key": "A", "text": "𝑎 = -1."}, {"key": "B", "text": "𝑎 = -1⁄2."}, {"key": "C", "text": "𝑎 = 1⁄2."}, {"key": "D", "text": "𝑎 = 1."}]'::jsonb, 'A', '', 'https://www.comvest.unicamp.br/vestibulares-anteriores/provas-e-gabaritos/', 2020, 'official', true, '{"bluex_id": "UNICAMP_2020_35", "assuntos_originais": ["mathematics"]}'::jsonb, '2026-10-16 19:55:30.178949+00', '2026-10-16 19:55:30.089+00'
